import{z as n,x as A,o as e,c as p,q as t,j as o,D as E,d as r,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"工艺窗口鉴定 PWQ","description":"","frontmatter":{"title":"工艺窗口鉴定 PWQ","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pwq.md","filePath":"litho/pwq.md","lastUpdated":1791413859000}'),B={name:"litho/pwq.md"};function d(D,a,h,P,C,c){const i=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="工艺窗口鉴定-pwq" tabindex="-1">工艺窗口鉴定 PWQ <a class="header-anchor" href="#工艺窗口鉴定-pwq" aria-label="Permalink to &quot;工艺窗口鉴定 PWQ&quot;">​</a></h1><div class="epigraph"><p>模型说窗还在，硅上未必还在。PWQ 把剂量与焦点故意拉到规格角，用检测而不是只靠 CD-SEM 平均，找出先死的那些场。</p><footer>—— 对照工艺窗口鉴定（PWQ）产线通称；与 FEM / E–D 矩阵及缺陷检测的公开衔接</footer></div><p><a href="/litho/pattern-matching">上一课</a>标出「长得像杀手」的 clips。缺口是实验：这些候选以及模型没见过的图形，在真实胶、真实扫描机上，窗口角是否先桥、先断、先掉孔。本课钉 PWQ（process window qualification）。全场模型签核的工具链，留给<a href="/litho/lrc-orc">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/ed-process-window">E–D 窗口</a> 用选定 gauge 的平均 CD 切窗；<a href="/litho/stochastic-process-window">随机窗</a> 用缺陷率切第二张窗。PWQ 是把后者做成品化：在产品或准产品版图上做焦点–剂量矩阵（或扫描机的 PWQ 序列），每场用缺陷检测扫桥连、断线、缺孔、残胶，再 SEM 复检。它回答的不是「某条线的 Bossung」，而是<strong>这层产品图形在窗角会不会出系统缺陷</strong>。</p><p>缺口是<strong>鉴定协议</strong>，不是再画一次均值窗。只在标称点做缺陷扫描，等于假设窗口矩形内部平坦——热点课已经否定这一点。</p><p><span class="marginnote">术语翻译：「缺陷窗」就是把每个（剂量, 焦点）格点上数出来的致命缺陷个数画成等高线——计数开始起飞的那条线，就是这层产品图形自己的窗边。它回答的不是「这条线宽了多少纳米」，而是「这个角上会不会批量出 killer」。</span></p><h3 id="pwq-不是-fem-的别名" tabindex="-1">PWQ 不是 FEM 的别名 <a class="header-anchor" href="#pwq-不是-fem-的别名" aria-label="Permalink to &quot;PWQ 不是 FEM 的别名&quot;">​</a></h3><p>FEM（focus-exposure matrix）常在测试芯片上量 CD。PWQ 强调产品相关图形 + 缺陷检测为主、CD 为辅。两者都动 \\((E,z)\\)，但判决物不同：一个是纳米，一个是 killer 计数。把 FEM 的 CD 合格当成 PWQ 通过，会把稀疏二维失效漏掉。</p><p><span class="marginnote">PWQ 场是「故意做坏」的场，不能流到良率账里当普通废品。批次与分派要隔离，否则 APC 会把鉴定矩阵当成漂移去补。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>版图：产品关键层，或把热点 clips 嵌进 PWQ 掩模。矩阵：剂量、焦点（有时加套刻偏移）覆盖规格矩形及以外一圈，用来看见悬崖位置。检测：亮场/暗场光学扫全场，电子束补小缺陷。判决：缺陷密度对 \\((E,z)\\) 的等高线，与均值 CD 窗求交。与 <a href="/litho/adi-aei">ADI/AEI</a> ：PWQ 常在 ADI 做，因为重工便宜；最终仍要抽 AEI，避免只鉴定胶上的窗。</p><p>匹配课的模板在这里被证实或证伪：硅上新杀手要回写模板库和模型残差。</p><p>矩阵不必是全规格的笛卡尔积：可先沿焦轴和剂量轴做十字，再在失败象限加密。Levinson 把工艺窗口写成可鉴定的面积；PWQ 把面积的判决物换成缺陷计数。扫描机公开的 PWQ 序列只是把这场鉴定编进曝光菜谱，不改变物理。矩阵规模受扫描机时间约束：角点必须含规格矩形顶点，中间点用来看悬崖斜率。缺陷检测配方与量产同一灵敏度，否则鉴定窗和出货窗对不上。</p>',14)),(e(),o(l,null,{default:E(()=>[s(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEM%5B%22FEM%EF%BC%9A%E6%B5%8B%E8%AF%95%E8%8A%AF%E7%89%87%22%5D%20--%3E%20CD%5B%22CD-SEM%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20CD%20--%3E%20MW%5B%22%E5%9D%87%E5%80%BC%20CD%20%E7%AA%97%EF%BC%88%E7%BA%B3%E7%B1%B3%E5%88%A4%E5%86%B3%EF%BC%89%22%5D%0A%20%20PWQ%5B%22PWQ%EF%BC%9A%E4%BA%A7%E5%93%81%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20INSP%5B%22%E5%85%A8%E5%9C%BA%E7%BC%BA%E9%99%B7%E6%89%AB%E6%8F%8F%22%5D%0A%20%20INSP%20--%3E%20KC%5B%22killer%20%E8%AE%A1%E6%95%B0%E7%AD%89%E9%AB%98%E7%BA%BF%22%5D%0A%20%20KC%20--%3E%20DW%5B%22%E7%BC%BA%E9%99%B7%E7%AA%97%EF%BC%88%E8%AE%A1%E6%95%B0%E5%88%A4%E5%86%B3%EF%BC%89%22%5D%0A%20%20MW%20--%3E%20INT%5B%22%E4%BA%A4%E9%9B%86%20%3D%20%E9%87%8F%E4%BA%A7%E5%81%9C%E9%9D%A0%E7%82%B9%22%5D%0A%20%20DW%20--%3E%20INT%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：一个 \\(5\\times5\\) 的全矩阵要 25 次曝光场；先用「十字」只打两轴约 9 个点，若失败集中在低剂量象限，再只在那个象限加 4-6 个点——扫描机时间省四成上下，悬崖位置照样看得见。</span></p><p><span class="marginnote">直觉类比：布点像医生体检——先量体温、血压这两条主线（焦轴与剂量轴的十字），哪项异常再对那个部位加拍 CT（失败象限加密）。全身 CT 扫一遍不是不行，是预约（机时）排不起。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离焦掉 NILS，二维线端和孔先掉；过剂量或欠剂量把桥/断推向相反方向。PWQ 检测看到的是这些失效的空间爆发，不是平均边的平移。扫描机序列把不同 \\((E,z)\\) 编进不同场，使一张版、一次过机完成矩阵——这是鉴定产能，不是日常曝光食谱。</p><p><span class="marginnote">常见误区：初学者容易以为「窗口矩形内部是平坦的，名义点没事就全没事」。实际上悬崖常贴着角点：二维线端与孔在离焦时最先失守，而 CD 平均值几乎不动。这正是 PWQ 必须把场故意推到规格角的原因。</span></p>',5)),(e(),o(l,null,{default:E(()=>[s(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLIP%5B%22%E7%83%AD%E7%82%B9%20%2F%20%E4%BA%A7%E5%93%81%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20MAT%5B%22E-z%20%E7%9F%A9%E9%98%B5%E6%9B%9D%E5%85%89%22%5D%0A%20%20MAT%20--%3E%20INSP%5B%22%E7%BC%BA%E9%99%B7%E6%A3%80%E6%B5%8B%22%5D%0A%20%20INSP%20--%3E%20REV%5B%22SEM%20%E5%A4%8D%E6%A3%80%22%5D%0A%20%20REV%20--%3E%20WIN%5B%22%E7%BC%BA%E9%99%B7%E7%AA%97%20%E2%88%A9%20CD%20%E7%AA%97%22%5D%0A%20%20WIN%20--%3E%20LIB%5B%22%E5%9B%9E%E5%86%99%E6%A8%A1%E6%9D%BF%E4%B8%8E%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>缺陷窗与均值 CD 窗的交集才是量产停靠点。只交 CD 窗，会把随机桥连和二维失效留在规格矩形的角上——随机窗课已经警告过，PWQ 是它的产品化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PWQ 覆盖不了所有产品邻域，也不覆盖腔体老化后的刻蚀窗。不编造某节点「PWQ 零缺陷」的公开数字。EUV 随机需要更大统计，单次 PWQ 矩阵可能不够。</p><p>后课默认：硅上缺陷窗是模型签核的锚；下一课 LRC/ORC 用模型在全场近似这场鉴定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PWQ 用产品图形的 \\((E,z)\\) 矩阵加缺陷检测鉴定窗口，不只靠 CD。</li><li>鉴定场必须与量产分派隔离。</li><li>新杀手回写匹配库与紧凑模型。</li><li>出处：PWQ 产线通称；Levinson 对工艺窗口与缺陷的讨论；检测工具公开方法。</li></ul>',6))])}const W=n(B,[["render",d]]);export{m as __pageData,W as default};
